    private lateinit var memo:Array<IntArray>;
    private fun dfs(pos:Int,previous:Int,tight:Boolean):Int{
        if(pos==digits.length)return 1;
        if(!tight&&memo[pos][previous]!=-1)return memo[pos][previous];
        val limit=if(tight)digits[pos]-'0' else 9;
        var ways=0L;
        for(digit in 0..limit){
            val next=if(previous==10&&digit==0)10 else if(previous==10||kotlin.math.abs(previous-digit)==1)digit else continue;
            ways=(ways+dfs(pos+1,next,tight&&digit==limit))%mod
        };
        val answer=ways.toInt();
        if(!tight)memo[pos][previous]=answer;
        return answer
    };
    private fun countUpTo(bound:String):Int{
        digits=bound;
        memo=Array(digits.length){
            IntArray(11){
                -1
            }
        };
        return dfs(0,10,true)
    };
    private fun stepping(value:String):Boolean{
        for(i in 1 until value.length)if(kotlin.math.abs(value[i]-value[i-1])!=1)return false;
        return true
    };
    fun countSteppingNumbers(low:String,high:String):Int{
        var answer=(countUpTo(high).toLong()-countUpTo(low)+if(stepping(low))1 else 0)%mod;
        if(answer<0)answer+=mod;
        return answer.toInt()
    }
}

